css:
@page { size: letter; margin: 16mm; }
.cx-invoice { font-family: "Plus Jakarta Sans", "Helvetica Neue", Arial, sans-serif; font-size: 10.5pt; color: #111827; }
.cx-invoice h1 { font-size: 16pt; margin: 0 0 2px; }
.cx-invoice h2 { font-size: 13pt; margin: 0; text-transform: uppercase; letter-spacing: .06em; color: #167f5b; }
.cx-invoice p { margin: 0 0 3px; }
.cx-invoice .muted { color: #6b7280; font-size: 9.5pt; }
.cx-inv-head { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 2px solid #167f5b; padding-bottom: 10px; margin-bottom: 14px; }
.cx-inv-id { text-align: right; }
.cx-inv-to { margin-bottom: 14px; }
.cx-invoice table { width: 100%; border-collapse: collapse; }
.cx-inv-lines th { text-align: left; font-size: 9pt; text-transform: uppercase; letter-spacing: .04em; color: #6b7280; border-bottom: 1px solid #d1d5db; padding: 6px 4px; }
.cx-inv-lines td { padding: 6px 4px; border-bottom: 1px solid #eef0f2; vertical-align: top; }
.cx-invoice .r { text-align: right; font-variant-numeric: tabular-nums; }
.cx-inv-totals { width: 55% !important; margin: 14px 0 0 auto; }
.cx-inv-totals td { padding: 4px; }
.cx-inv-totals .strong td { font-weight: 700; border-top: 1px solid #111827; }
.cx-inv-logo { height: 38px; max-width: 160px; object-fit: contain; margin-bottom: 6px; display: block; }
.cx-inv-notes { margin-top: 26px; color: #374151; white-space: pre-wrap; }
